import {directedMeshEdges,boundaryPaths,meshEdgeKey} from './mesh-boundaries.js';
export function selectMeshBoundaryLoops(data,seeds){
 if(!Array.isArray(seeds)||!seeds.length||seeds.some(edge=>!Array.isArray(edge)||edge.length!==2||edge.some(id=>!Number.isInteger(id)||id<0||id>=data.vertices.length)||edge[0]===edge[1]))throw Error('선택할 경계 간선을 지정하세요.');const all=directedMeshEdges(data);if([...all.values()].some(edge=>edge.invalid))throw Error('비다양체·뒤집힌 메시의 경계를 먼저 정리하세요.');const chosen=new Set(seeds.map(edge=>{const key=meshEdgeKey(...edge);if(all.get(key)?.count!==1)throw Error('열린 면의 경계 간선을 선택하세요.');return key;})),paths=boundaryPaths([...all.values()].filter(edge=>edge.count===1)),loops=paths.filter(path=>path.ids.some((id,i)=>chosen.has(meshEdgeKey(id,path.ids[(i+1)%path.ids.length]))));if(!loops.length||loops.some(path=>!path.closed))throw Error('닫힌 경계 루프를 확인하세요.');const edges=loops.flatMap(path=>path.ids.map((id,i)=>[id,path.ids[(i+1)%path.ids.length]]));return{edges,vertices:[...new Set(edges.flat())],loops:loops.length,total:edges.length};
}
export function readMeshBoundaryLoops(data,{edges,offset=0,limit=128}={}){if(!Number.isInteger(offset)||offset<0||!Number.isInteger(limit)||limit<1||limit>256)throw Error('경계 페이지는 offset0 이상·limit1~256이에요.');const selected=selectMeshBoundaryLoops(data,edges);return{loops:selected.loops,total:selected.total,vertexCount:selected.vertices.length,offset,limit,items:selected.edges.slice(offset,offset+limit).map(edge=>[...edge]),nextOffset:offset+limit<selected.total?offset+limit:null,readOnly:true};}
export function applyMeshBoundarySelection(editor){const selected=selectMeshBoundaryLoops(editor.doc.data,[...editor.edges.values()]);editor.edges=new Map(selected.edges.map(edge=>[meshEdgeKey(...edge),edge]));editor.vertices=new Set(selected.vertices);editor.faces.clear();editor.selectionMode='edge';editor.updateSelection();editor.render();return{loops:selected.loops,edges:selected.total,vertices:selected.vertices.length,readOnly:true};}
export const meshBoundarySelectionContract={read:'world.mesh.boundary.read',input:'one or more unique/reversed boundary seed edges, existing mesh/expectedRevision; offset0+,limit1..256 default128 for AI edge page',selection:'Expand seeds to their whole closed oriented boundary loops, including holes/disconnected islands. Distinct loops union once; preserves geometry/UV/normal/data/revision/dirty/Undo. Human edge selection updates existing point/line overlay.',validation:'Reject interior/missing/degenerate seeds, branched/nonmanifold/reversed neighborhoods and nonclosed paths; never choose arbitrary outgoing edges.',limits:'Boundary loops only; no inferred interior quad edge loops or automatic vertex seam welding; full mesh edge scan/boundary build remains. Source/headless only.'};
